import { describe, expect, it } from "vitest"
import { formatDate, KINDS, releases, screenshotsOf, releaseForHash, thumbnail } from "@/lib/changelog"
import { release } from "@/test/fixtures"

// src/changelog.json is regenerated by every release (.github/scripts/changelog.py)
describe("the baked-in changelog", () => {
  it("lists releases newest first, each with at least one change", () => {
    expect(releases.length).toBeGreaterThan(0)
    const dates = releases.map((r) => r.date)
    expect(dates).toEqual(dates.toSorted().toReversed())
    for (const r of releases) {
      expect(r.tag).toBe(`v${r.version}`)
      expect(r.entries.length).toBeGreaterThan(0)
    }
  })

  it("gives every change a known kind and a unique slug within its release", () => {
    for (const r of releases) {
      for (const e of r.entries) expect(KINDS).toContain(e.kind)
      expect(new Set(r.entries.map((e) => e.slug)).size).toBe(r.entries.length)
    }
  })
})

describe("screenshotsOf", () => {
  it("lists a release's pictures in entry order, each with the change it shows", () => {
    expect(screenshotsOf(release)).toEqual([
      { ...release.entries[0].screenshots[0], entry: "Engineers lay bridges" },
      { ...release.entries[0].screenshots[1], entry: "Engineers lay bridges" },
    ])
  })
})

describe("formatDate", () => {
  it("reads a release date as that day wherever the visitor is", () => {
    // noon UTC, so no timezone moves it to the day before or after
    expect(formatDate("2026-10-16")).toMatch(/16/)
  })

  it("leaves something it can't read as it is", () => {
    expect(formatDate("soon")).toBe("soon")
  })
})

it("opens old releases and individual changes without crashing on malformed links", () => {
  const older = releases[1]
  expect(releaseForHash(`#${older.tag}`)).toBe(older)
  expect(releaseForHash(`#${older.tag}-${older.entries[0].slug}`)).toBe(older)
  for (const hash of ["", "#unknown", "#%E0%A4%A", `#${older.tag}-missing`]) {
    expect(releaseForHash(hash)).toBe(releases[0])
  }
})

describe("changelog thumbnails", () => {
  it("names the site's small copy of a released picture, and leaves anything else alone", () => {
    const raw = "https://raw.githubusercontent.com/Dynasty9/Frontline/main/changelog"
    expect(thumbnail(`${raw}/v1.0.13/character-playground/playground.png`)).toBe(
      "/changelog-thumbs/v1.0.13/character-playground/playground.png.jpg"
    )
    expect(thumbnail(`${raw}/v1.0.13/blast-impact-and-sound/after.jpg`)).toBe(
      "/changelog-thumbs/v1.0.13/blast-impact-and-sound/after.jpg.jpg"
    )
    // a clip, and a picture from somewhere else, have no small copy
    expect(thumbnail(`${raw}/v1.0.13/blast-impact-and-sound/after.webm`)).toBe(
      `${raw}/v1.0.13/blast-impact-and-sound/after.webm`
    )
    expect(thumbnail("/media/hero.jpg")).toBe("/media/hero.jpg")
  })
})
